import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class XmlElementWrapperPluginTest {

    @Mock
    private Outline outlineMock;

    public XmlElementWrapperPluginTest() {
        MockitoAnnotations.initMocks(this);
    }

    @Test
    public void runInternal_SucceedsWhenOutlineIsNotNull() throws Exception {
        when(outlineMock != null).thenReturn(true);
        XmlElementWrapperPlugin plugin = new XmlElementWrapperPlugin();
        boolean result = plugin.runInternal(outlineMock);
        assertTrue(result);
    }

    @Test
    public void runInternal_FailsWhenOutlineIsNull() throws Exception {
        when(outlineMock == null).thenReturn(false);
        XmlElementWrapperPlugin plugin = new XmlElementWrapperPlugin();
        boolean result = plugin.runInternal(outlineMock);
        assertFalse(result);
    }

    @Test
    public void runInternal_ThrowsIOExceptionWhenReadingFileFails() throws Exception, IOException {
        when(outlineMock.toString()).thenThrow(IOException.class);
        XmlElementWrapperPlugin plugin = new XmlElementWrapperPlugin();
        try {
            plugin.runInternal(outlineMock);
            assertEquals("IOException", "Error reading file", Mockito.anyString());
        } catch (IOException e) {
            assertEquals(e.getMessage(), "Error reading file");
        }
    }

    @Test
    public void runInternal_ThrowsClassNotFoundExceptionWhenClassNotFinds() throws Exception, ClassNotFoundException {
        when(outlineMock.toString()).thenReturn("com.sun.tools.xjc.addon.xew.XmlElementWrapperPlugin");
        XmlElementWrapperPlugin plugin = new XmlElementWrapperPlugin();
        try {
            plugin.runInternal(outlineMock);
            assertEquals("ClassNotFoundException", "Error finding class", Mockito.anyString());
        } catch (ClassNotFoundException e) {
            assertEquals(e.getMessage(), "Error finding class");
        }
    }

}
